/* Token Radar theme: deep navy canvas, teal accent, amber value. One palette,
   one radius, one spacing scale; everything else is layout. */
:root {
  --bg: #0d1622;
  --panel: #14202f;
  --panel2: #1a2a3d;
  --ink: #e8eef4;
  --muted: #9fb0c3;
  --line: #2a3d52;
  --teal: #2dd4bf;
  --teal-dim: #0f766e;
  --amber: #fbbf24;
  --red: #f87171;
  --green: #4ade80;
  --radius: 10px;
  --s1: 4px; --s2: 8px; --s3: 12px; --s4: 16px; --s5: 24px; --s6: 32px;
  --font: system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, monospace;
}
* { box-sizing: border-box; }
body {
  margin: 0; background: var(--bg); color: var(--ink);
  font: 400 15px/1.55 var(--font);
}
h1 { font-size: 30px; line-height: 1.15; margin: var(--s2) 0 var(--s3); letter-spacing: -0.02em; }
h2 { font-size: 17px; margin: 0 0 var(--s2); }
p { margin: 0; }
a { color: var(--teal); }
button, input, select { font: inherit; color: inherit; }
:focus-visible { outline: 2px solid var(--teal); outline-offset: 2px; }

.shell { max-width: 1180px; margin: 0 auto; padding: var(--s5) var(--s5) var(--s6); }
.top { display: flex; gap: var(--s5); justify-content: space-between; align-items: flex-start; }
.eyebrow { color: var(--teal); font: 600 12px/1.4 var(--mono); letter-spacing: 0.14em; margin: 0; }
.lede { color: var(--muted); max-width: 62ch; }
.stats { display: grid; grid-template-columns: repeat(2, minmax(110px, 1fr)); gap: var(--s2); flex: none; }
.stat { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: var(--s3) var(--s4); }
.stat b { display: block; font: 600 20px/1.2 var(--mono); color: var(--amber); }
.stat span { color: var(--muted); font-size: 12px; }

.method {
  margin-top: var(--s5); background: var(--panel); border: 1px solid var(--line);
  border-left: 3px solid var(--teal); border-radius: var(--radius); padding: var(--s4) var(--s5);
}
.method p { color: var(--muted); margin-top: var(--s2); max-width: 100ch; }
.method p b { color: var(--ink); font-family: var(--mono); font-size: 13px; }

.controls {
  display: flex; flex-wrap: wrap; gap: var(--s3); align-items: end;
  margin: var(--s5) 0 var(--s4);
}
.controls label { display: grid; gap: var(--s1); color: var(--muted); font-size: 12px; }
.controls input, .controls select {
  min-height: 38px; padding: 0 var(--s3); border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--panel); min-width: 150px;
}
.controls input { min-width: 240px; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }

.detail {
  background: var(--panel2); border: 1px solid var(--teal-dim); border-radius: var(--radius);
  padding: var(--s4) var(--s5); margin-bottom: var(--s4);
}
.detail h2 { font-size: 22px; }
.detail h2 small { color: var(--muted); font: 400 13px var(--font); margin-left: var(--s2); }
.detail .meta { display: flex; flex-wrap: wrap; gap: var(--s2) var(--s4); color: var(--muted); font-size: 13px; margin: var(--s2) 0 var(--s3); }
.detail .meta b { color: var(--ink); font-family: var(--mono); font-weight: 600; }
.breakdown { display: flex; flex-wrap: wrap; gap: var(--s2); margin-bottom: var(--s3); }
.chip { background: var(--panel); border: 1px solid var(--line); border-radius: 999px; padding: var(--s1) var(--s3); font: 500 12px var(--mono); }
.chip b { color: var(--amber); }
.detail ol { margin: var(--s2) 0 0; padding-left: 20px; display: grid; gap: var(--s2); }
.detail li { color: #d5dee8; }
.detail li::marker { color: var(--teal); font-weight: 700; }
.detail .close { float: right; background: transparent; border: 1px solid var(--line); border-radius: var(--radius); padding: var(--s1) var(--s3); color: var(--muted); cursor: pointer; }

.board { width: 100%; border-collapse: collapse; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
.board th, .board td { padding: var(--s3) var(--s4); text-align: left; border-bottom: 1px solid var(--line); }
.board thead th { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; background: var(--panel2); }
.board th button { background: none; border: 0; padding: 0; color: inherit; font: inherit; text-transform: inherit; letter-spacing: inherit; cursor: pointer; }
.board th button:hover { color: var(--teal); }
.board tbody tr { cursor: pointer; }
.board tbody tr:hover, .board tbody tr.sel { background: #1e3247; }
.board td.num, .board th.num { text-align: right; font-family: var(--mono); font-size: 13px; }
.board td.val { color: var(--amber); font-weight: 600; }
.board td.name b { display: block; }
.board td.name small { color: var(--muted); font-family: var(--mono); font-size: 12px; }
.up { color: var(--green); } .down { color: var(--red); } .flat { color: var(--muted); }
.tag { display: inline-block; background: var(--teal-dim); color: #d9fff8; border-radius: 999px; padding: 1px 8px; font-size: 11px; margin-left: 6px; vertical-align: 1px; }
.empty { padding: var(--s5); text-align: center; color: var(--muted); }
.foot { color: var(--muted); font-size: 13px; margin-top: var(--s4); }
@media (max-width: 760px) {
  .top { flex-direction: column; }
  .stats { grid-template-columns: repeat(2, 1fr); width: 100%; }
  .board td:nth-child(5), .board th:nth-child(5) { display: none; }
}
